BEGIN TRANSACTION;
CREATE TABLE decisions (
          decision_id TEXT PRIMARY KEY, prediction_id TEXT NOT NULL REFERENCES predictions(prediction_id),
          quote_id TEXT REFERENCES quotes(quote_id), event_id TEXT NOT NULL,
          created_at TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE deliveries (
          delivery_id INTEGER PRIMARY KEY AUTOINCREMENT, outbox_id TEXT NOT NULL REFERENCES outbox(outbox_id),
          attempted_at TEXT NOT NULL, success INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE dispatch_claims (
          outbox_id TEXT PRIMARY KEY REFERENCES outbox(outbox_id), claimed_at TEXT NOT NULL);
CREATE TABLE models (
          model_id TEXT PRIMARY KEY, registered_at TEXT NOT NULL,
          research_status TEXT NOT NULL, artifact_sha256 TEXT, payload TEXT NOT NULL);
CREATE TABLE outbox (
          outbox_id TEXT PRIMARY KEY, event_id TEXT NOT NULL UNIQUE,
          decision_id TEXT NOT NULL REFERENCES decisions(decision_id), created_at TEXT NOT NULL,
          expires_at TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE predictions (
          prediction_id TEXT PRIMARY KEY, event_id TEXT NOT NULL, model_id TEXT NOT NULL,
          generated_at TEXT NOT NULL, ingested_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE quotes (
          quote_id TEXT PRIMARY KEY, event_id TEXT NOT NULL, observed_at TEXT NOT NULL,
          ingested_at TEXT NOT NULL, starts_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE settlements (
          settlement_id TEXT PRIMARY KEY, event_id TEXT NOT NULL UNIQUE,
          recorded_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE INDEX quotes_event ON quotes(event_id, observed_at);
CREATE TRIGGER immutable_models_update BEFORE UPDATE ON models BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_models_delete BEFORE DELETE ON models BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_quotes_update BEFORE UPDATE ON quotes BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_quotes_delete BEFORE DELETE ON quotes BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_predictions_update BEFORE UPDATE ON predictions BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_predictions_delete BEFORE DELETE ON predictions BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_decisions_update BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_decisions_delete BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_outbox_update BEFORE UPDATE ON outbox BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_outbox_delete BEFORE DELETE ON outbox BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_dispatch_claims_update BEFORE UPDATE ON dispatch_claims BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_dispatch_claims_delete BEFORE DELETE ON dispatch_claims BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_deliveries_update BEFORE UPDATE ON deliveries BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_deliveries_delete BEFORE DELETE ON deliveries BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_settlements_update BEFORE UPDATE ON settlements BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
CREATE TRIGGER immutable_settlements_delete BEFORE DELETE ON settlements BEGIN SELECT RAISE(ABORT, 'append-only audit table'); END;
DELETE FROM "sqlite_sequence";
COMMIT;
